import{a as e,i as t,r as n,t as r}from"./app-CC6Ai1Vx.js";var i=JSON.parse(`{"path":"/guide/setu.html","title":"随机色图","lang":"zh-CN","frontmatter":{},"git":{"updatedTime":1789756687000,"contributors":[{"name":"ShiroMizu","username":"","email":"ShiroMizuTan@163.com","commits":1}],"changelog":[{"hash":"c65951314429d1cc5323024a3b97f28aae89d9c6","time":1789756687000,"email":"ShiroMizuTan@163.com","author":"ShiroMizu","message":"docs: add setu command page"}]},"filePathRelative":"guide/setu.md"}`),a={name:`setu.md`};function o(r,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[t(`<h1 id="随机色图" tabindex="-1"><a class="header-anchor" href="#随机色图"><span>随机色图</span></a></h1><div class="hint-container tip"><p class="hint-container-title">提示</p><p>该指令必须带 <code>.</code> 前缀，聊天中偶然出现关键词不会触发。</p></div><h2 id="获取随机图片" tabindex="-1"><a class="header-anchor" href="#获取随机图片"><span>获取随机图片</span></a></h2><table><thead><tr><th>指令</th><th>参数</th><th>示例</th><th>说明</th></tr></thead><tbody><tr><td><code>setu</code> / <code>色图</code> / <code>来份色图</code></td><td>无</td><td><code>.setu</code></td><td>随机获取一张 Pixiv 插图</td></tr><tr><td><code>setu</code></td><td><code>标签</code></td><td><code>.setu 猫</code></td><td>按标签筛选图片</td></tr><tr><td><code>setu</code></td><td><code>标签 标签</code></td><td><code>.setu 白丝 制服</code></td><td>多个标签同时匹配</td></tr></tbody></table><h2 id="标签写法" tabindex="-1"><a class="header-anchor" href="#标签写法"><span>标签写法</span></a></h2><table><thead><tr><th>写法</th><th>示例</th><th>说明</th></tr></thead><tbody><tr><td>单个标签</td><td><code>.setu 猫</code></td><td>匹配带有该标签的作品</td></tr><tr><td>多个标签</td><td><code>.setu 猫 白丝</code></td><td>需同时满足全部标签，最多 3 个</td></tr></tbody></table><p>同一个标签内可以用 <code>|</code> 表示「满足其一」，例如 <code>.setu 萝莉|少女</code> 会匹配带有萝莉或少女标签的作品。</p><h2 id="说明" tabindex="-1"><a class="header-anchor" href="#说明"><span>说明</span></a></h2><ul><li>每次返回一张图片，并附带作品标题、PID 和作者。</li><li>每人有 15 秒冷却，冷却中会提示剩余秒数。</li><li>未命中标签时会提示「没有找到相关作品」，更换标签重试即可。</li></ul><div class="hint-container tip"><p class="hint-container-title">提示</p><p>图片来自 Pixiv，版权归原作者所有。</p></div>`,10)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};